INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, search_content) VALUES ('47ed0d19-9151-4877-824a-e71f85229c83', '夜發三泉即事', '夜发三泉即事', 'c31812a1-6251-4f50-8131-7eaa19122f40', '唐', '暗發三泉山，窮秋聽騷屑。\\n北林夜鳴雨，南望曉成雪。\\n祗詠北風涼，詎知南土熱。\\n沙溪忽沸渭，石道乍明滅。\\n宛若銀磧橫，復如瑤臺結。\\n指程賦所戀，遇虞不遑歇。\\n重纊濡莫解，懸旌凍猶揭。\\n下奔泥棧榰，上覯雲梯設。\\n[搏]頰羸馬頓，回眸惴人跌。\\n憧憧往復還，心注思逾切。\\n冉冉年將病，力困衰怠竭。\\n天彭信方隅，地勢誠斗絕。\\n忝曳尚書履，叨兼使臣節。\\n京坻有歲饒，亭障無邊孽。\\n歸奏丹墀左，騫能俟來哲。', '', 'shi', '', '夜發三泉即事 shi');